double sfd_throttle_to_speed(double u, double w_min, double w_max, double k)
{
    return w_min + (w_max - w_min)*sqrt(k*u*u + u*(1 - k));
}

/* spec.discretization.rk4_step: s + h/6 (k1 + 2 k2 + 2 k3 + k4). */
static void rk4(const double *s, const double *k1, const double *k2, const double *k3,
                const double *k4, double h, double *out)
{
    for (int i = 0; i < SFD_NS; i++) {
        out[i] = s[i] + (h / 6) * (k1[i] + 2 * k2[i] + 2 * k3[i] + k4[i]);
    }
}

void sfd_rk4_step(const double *s, const double *u, const double *p, double dt, double *out)
{
    double k1[SFD_NS], k2[SFD_NS], k3[SFD_NS], k4[SFD_NS], x[SFD_NS];
    sfd_statedot(s, u, p, k1);
    for (int i = 0; i < SFD_NS; i++) x[i] = s[i] + (dt / 2) * k1[i];
    sfd_statedot(x, u, p, k2);
    for (int i = 0; i < SFD_NS; i++) x[i] = s[i] + (dt / 2) * k2[i];
    sfd_statedot(x, u, p, k3);
    for (int i = 0; i < SFD_NS; i++) x[i] = s[i] + dt * k3[i];
    sfd_statedot(x, u, p, k4);
    rk4(s, k1, k2, k3, k4, dt, out);
}

/* The split right-hand side at stage time t (spec.motor.exact_exp_step): the rotor speeds on
   their closed form, their own slots held. */
static void split(const double *x, const double *s0, const double *u, const double *p,
                  double t, double *k)
{
    double y[SFD_NS];
    const double decay = exp(-t / p[SFD_P_TAU_M]);
    for (int i = 0; i < 13; i++) y[i] = x[i];
    for (int i = 0; i < SFD_N; i++) y[13 + i] = u[i] + (s0[13 + i] - u[i]) * decay;
    sfd_statedot(y, u, p, k);
    for (int i = 0; i < SFD_N; i++) k[13 + i] = 0.0;
}

void sfd_exact_exp_step(const double *s, const double *u, const double *p, double dt, double *out)
{
    double k1[SFD_NS], k2[SFD_NS], k3[SFD_NS], k4[SFD_NS], x[SFD_NS];
    split(s, s, u, p, 0.0, k1);
    for (int i = 0; i < SFD_NS; i++) x[i] = s[i] + (dt / 2) * k1[i];
    split(x, s, u, p, dt / 2, k2);
    for (int i = 0; i < SFD_NS; i++) x[i] = s[i] + (dt / 2) * k2[i];
    split(x, s, u, p, dt / 2, k3);
    for (int i = 0; i < SFD_NS; i++) x[i] = s[i] + dt * k3[i];
    split(x, s, u, p, dt, k4);
    rk4(s, k1, k2, k3, k4, dt, out);
    const double decay = exp(-dt / p[SFD_P_TAU_M]);
    for (int i = 0; i < SFD_N; i++) out[13 + i] = u[i] + (s[13 + i] - u[i]) * decay;
}

void sfd_post_step(double *s, double rotor_speed_min, double rotor_speed_max)
{
    const double norm = sqrt(s[6] * s[6] + s[7] * s[7] + s[8] * s[8] + s[9] * s[9]);
    for (int i = 6; i < 10; i++) s[i] /= norm;
    for (int i = 13; i < SFD_NS; i++) {
        s[i] = fmin(fmax(s[i], rotor_speed_min), rotor_speed_max);
    }
}

void sfd_advance(double *s, const double *u, const double *p, double dt, int steps,
                 double rotor_speed_min, double rotor_speed_max)
{
    double next[SFD_NS];
    for (int k = 0; k < steps; k++) {
        sfd_exact_exp_step(s, u, p, dt, next);
        sfd_post_step(next, rotor_speed_min, rotor_speed_max);
        for (int i = 0; i < SFD_NS; i++) s[i] = next[i];
    }
}
